PRAGMA temp_store = MEMORY;
CREATE TEMP TABLE {Table-Name}({Col-Name}, {Col-Name} AS({GenCol-Expr}) CHECK(NULL) UNIQUE NOT NULL, {Col-Name} CHECK({Expr}) PRIMARY KEY) WITHOUT ROWID;
CREATE UNIQUE INDEX {Table-Name} ON {Table-Name}(CAST({Expr} AS INT)) WHERE {Expr};
REINDEX;
INSERT INTO {Table-Name}({Col-Name}) VALUES ({Literal}), ({Literal});
REPLACE INTO {Table-Name}({Col-Name}, {Col-Name}) VALUES ({Literal}, {Literal}), ({Blob-Literal}, NULL);
UPDATE {Table-Name} SET {Col-Name} = {Expr}
